const assert=require('node:assert/strict');
const fs=require('node:fs');
const vm=require('node:vm');
const path=require('node:path');

const source=fs.readFileSync(path.join(__dirname,'../internal/webassets/static/account-paged.js'),'utf8');
const elements=new Map();
const element=id=>{if(!elements.has(id))elements.set(id,{id,value:'',hidden:false,textContent:'',disabled:false,dataset:{},classList:{add(){},remove(){},toggle(){}},setAttribute(name,value){this[name]=value;}});return elements.get(id);};
const body={classList:{values:new Set(),add(value){this.values.add(value);},remove(value){this.values.delete(value);},toggle(value,on){on?this.values.add(value):this.values.delete(value);}}};
let shown=null,requests=[];
const response={workspace_view:'accounts_page',office_id:'three',page:1,page_size:50,total:2,pages:1,published_total:1,computer_total:1,accounts:[{id:'a'},{id:'b'}],matching_ids:['a','b'],record_versions:{},cursor:1,user:{id:1},statuses:[],date:'2026-11-21',today:'2026-11-21',computers:[],offices:[],phone_devices:{devices:[]},phone_cards:{cards:[]},publishing_layout:{enabled:false,cells:[]},nurture:{records:[]},device_workflow:{enabled:false,units:[]}};
const context={URLSearchParams,AbortController,setTimeout,clearTimeout,console,page:'accounts',activeOffice:'three',activeLifecyclePreset:'',accountPageIndex:9,document:{body,getElementById:element,createElement:()=>({className:'',innerHTML:'',append(){}})},api:async request=>{requests.push(String(request));return response;},showBoard:value=>{shown=value;element('date').value=value.date;},render(){},load(){throw Error('legacy load should not run');}};
context.window=context;vm.createContext(context);vm.runInContext(source,context);

(async()=>{
 assert.equal(context.AccountPaged.intent(),true);
 assert.equal(context.AccountPaged.eligible(),true);
 await context.AccountPaged.load(1);
 assert.equal(requests[0],'/api/accounts?office_id=three&page=1');
 assert.equal(context.AccountPaged.active(),true);
 assert.equal(context.accountPageIndex,1);
 assert.equal(shown,response);
 assert.equal(context.AccountPaged.canAct(),true);
 context.AccountPaged.restorePage(1);
 assert.equal(context.AccountPaged.canAct(),true,'a restored, unchanged page should be usable immediately');
 assert.deepEqual([...context.AccountPaged.matchingIds()],['a','b']);
 assert.equal(context.AccountPaged.total(),2);
 element('query').value='账号';element('accountDouyinQuery').value='DY-1';element('accountIdQuery').value='#A-1';element('status').value='正常';
 await context.AccountPaged.load(1);
 assert.equal(requests[1],'/api/accounts?office_id=three&page=1&date=2026-11-21&query=%E8%B4%A6%E5%8F%B7&douyin_id=DY-1&account_id=A-1&status=%E6%AD%A3%E5%B8%B8');
 const read=context.api;
 let finish;
 context.api=()=>new Promise(resolve=>{finish=resolve;});
 const old=context.AccountPaged.load(1);
 element('query').value='更晚的筛选';
 context.AccountPaged.schedule();
 assert.equal(context.AccountPaged.canAct(),false);
 finish({...response,accounts:[{id:'old'}]});
 assert.equal(await old,false);
 assert.equal(shown,response);
 context.AccountPaged.cancelPending();
 assert.equal(context.AccountPaged.canAct(),false);
 context.api=async()=>{throw Error('synthetic unavailable');};
 assert.equal(await context.AccountPaged.ensureLegacy(),false);
 assert.equal(context.AccountPaged.active(),true);
 assert.equal(element('loadError').hidden,false);
 context.api=read;
 await context.AccountPaged.ensureLegacy();
 assert.equal(requests[2],'/api/board?version_scope=day&compact=accounts&date=2026-11-21');
 assert.equal(context.AccountPaged.active(),false);
 element('accountType').value='大号';
 assert.equal(context.AccountPaged.eligible(),false);
 element('accountType').value='';
 await context.AccountPaged.load(1);
 let cleared=false;
 context.clearPagedAccountView=()=>{cleared=true;};
 context.api=async()=>{throw Object.assign(Error('Office grant revoked'),{status:403});};
 assert.equal(await context.AccountPaged.load(1),false);
 assert.equal(cleared,true);
 assert.equal(context.AccountPaged.active(),false);
 assert.deepEqual([...context.AccountPaged.matchingIds()],[]);
 console.log('account-paged tests passed');
})().catch(error=>{console.error(error);process.exitCode=1;});
